const input = $input.first().json;
const data = Array.isArray(input) ? input[0] : input;

if (!data?.current || !data?.daily) {
  throw new Error("Missing current or daily weather data.");
}

// Format date and time, e.g. 25 Oct 2026, 09:00 AM
function formatDateTime(dateTime) {
  return new Date(dateTime).toLocaleString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
    timeZone: "Europe/London",
  });
}

// Format date only, e.g. 25 Oct 2026
function formatDate(dateTime) {
  return new Date(dateTime).toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "Europe/London",
  });
}

// Format time only, e.g. 07:08 AM
function formatTime(dateTime) {
  return new Date(dateTime).toLocaleTimeString("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
    timeZone: "Europe/London",
  });
}

const weatherReport = {
  city: "Glasgow",

  // Report date and time
  reportTime: formatDateTime(data.current.time),

  // Current weather conditions
  temperatureC: data.current.temperature_2m,
  feelsLikeC: data.current.apparent_temperature,
  humidityPercent: data.current.relative_humidity_2m,
  precipitationMm: data.current.precipitation,
  windSpeedKmh: data.current.wind_speed_10m,

  // Today's forecast
  forecastDate: formatDate(data.daily.time[0]),
  maxTemperatureC: data.daily.temperature_2m_max[0],
  minTemperatureC: data.daily.temperature_2m_min[0],
  precipitationProbabilityPercent:
    data.daily.precipitation_probability_max[0],

  // Sunrise and sunset
  sunrise: formatTime(data.daily.sunrise[0]),
  sunset: formatTime(data.daily.sunset[0]),
};

return [
  {
    json: weatherReport,
  },
];
